import java.util.ArrayList;
import java.util.List;

// No JDBC driver is available here, so the classes after the main class are a tiny in-memory
// stand-in shaped like java.sql. With a real driver you would import java.sql.* instead.
public class JdbcStudentsDemo {
    static final String INSERT = "INSERT INTO students (id, name, age) VALUES (?, ?, ?)";
    static final String QUERY = "SELECT id, name, age FROM students WHERE age >= ?";

    static void insert(PreparedStatement ps, int id, String name, int age) throws SQLException {
        ps.setInt(1, id); // parameter indices start at 1
        ps.setString(2, name);
        ps.setInt(3, age);
        ps.executeUpdate();
    }

    public static void main(String[] args) throws SQLException {
        Connection kept;
        // Real: try (Connection conn = DriverManager.getConnection("jdbc:h2:mem:school", "sa", ""))
        try (Connection conn = DriverManager.getConnection("jdbc:mem:school")) {
            kept = conn;
            System.out.println("connected to jdbc:mem:school, autoCommit = " + conn.getAutoCommit());
            conn.setAutoCommit(false); // group the next statements into one transaction
            PreparedStatement ps = conn.prepareStatement(INSERT);
            insert(ps, 1, "Ana", 20);
            insert(ps, 2, "Luis", 22);
            insert(ps, 3, "Marta", 25);
            conn.commit();
            System.out.println("tx 1: inserted Ana, Luis, Marta -> commit");

            try {
                insert(ps, 4, "Diego", 23);
                insert(ps, 2, "Luisa", 30); // duplicate primary key
                conn.commit();
            } catch (SQLException e) {
                conn.rollback(); // undo everything since the last commit, Diego included
                System.out.println("tx 2: SQLException: " + e.getMessage() + " -> rollback");
            }

            PreparedStatement query = conn.prepareStatement(QUERY);
            query.setInt(1, 21);
            System.out.println(QUERY + "  [1] = 21");
            ResultSet rs = query.executeQuery();
            while (rs.next()) { // the cursor starts before the first row
                System.out.println("  " + rs.getInt("id") + " " + rs.getString("name") + " " + rs.getInt("age"));
            }
        }
        System.out.println("closed by try-with-resources: " + kept.isClosed());
    }
}

class SQLException extends Exception {
    SQLException(String message) { super(message); }
}

record Row(int id, String name, int age) {}

class DriverManager {
    static Connection getConnection(String url) throws SQLException {
        if (!url.startsWith("jdbc:mem:")) throw new SQLException("No suitable driver found for " + url);
        return new Connection();
    }
}

class Connection implements AutoCloseable {
    private List<Row> table = new ArrayList<>(); // committed rows
    private List<Row> pending = null;             // working copy of an open transaction
    private boolean autoCommit = true, closed = false;

    boolean getAutoCommit() { return autoCommit; }
    void setAutoCommit(boolean on) { autoCommit = on; }
    boolean isClosed() { return closed; }
    PreparedStatement prepareStatement(String sql) { return new PreparedStatement(this, sql); }
    List<Row> rows() { return pending != null ? pending : table; }

    void write(Row row) throws SQLException {
        if (!autoCommit && pending == null) pending = new ArrayList<>(table); // transaction begins
        for (Row r : rows()) if (r.id() == row.id()) throw new SQLException("duplicate primary key " + row.id());
        rows().add(row);
    }

    void commit() { if (pending != null) table = pending; pending = null; }
    void rollback() { pending = null; }
    public void close() { closed = true; }
}

class PreparedStatement {
    private final Connection conn;
    private final String sql;
    private final Object[] params = new Object[4]; // slot 0 unused: JDBC indices are 1-based

    PreparedStatement(Connection conn, String sql) { this.conn = conn; this.sql = sql; }
    void setInt(int index, int value) { params[index] = value; }
    void setString(int index, String value) { params[index] = value; }

    int executeUpdate() throws SQLException { // understands only the INSERT above
        conn.write(new Row((Integer) params[1], (String) params[2], (Integer) params[3]));
        return 1;
    }

    ResultSet executeQuery() { // understands only the SELECT above
        List<Row> result = new ArrayList<>();
        for (Row r : conn.rows()) if (r.age() >= (Integer) params[1]) result.add(r);
        return new ResultSet(result);
    }
}

class ResultSet {
    private final List<Row> rows;
    private int cursor = -1; // before the first row

    ResultSet(List<Row> rows) { this.rows = rows; }
    boolean next() { return ++cursor < rows.size(); }
    int getInt(String column) { return column.equals("id") ? rows.get(cursor).id() : rows.get(cursor).age(); }
    String getString(String column) { return rows.get(cursor).name(); }
}

