#include <iostream>
#include <map>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

// No JDBC here: a tiny in-memory stand-in shaped like java.sql (DriverManager, Connection, ...)
struct SQLException : std::runtime_error {
    using std::runtime_error::runtime_error;
};

struct Row {
    int id;
    std::string name;
    int age;
};

class ResultSet {
public:
    explicit ResultSet(std::vector<Row> rows) : rows_(std::move(rows)) {}
    bool next() { return ++cursor_ < static_cast<int>(rows_.size()); }
    int getInt(const std::string& column) const { return column == "id" ? rows_[cursor_].id : rows_[cursor_].age; }
    std::string getString(const std::string&) const { return rows_[cursor_].name; }

private:
    std::vector<Row> rows_;
    int cursor_ = -1; // before the first row
};

class Connection {
public:
    bool getAutoCommit() const { return autoCommit_; }
    void setAutoCommit(bool on) { autoCommit_ = on; }
    bool isClosed() const { return closed_; }
    void close() { closed_ = true; }
    std::vector<Row>& rows() { return pending_ ? *pending_ : table_; }

    void write(const Row& row) {
        if (!autoCommit_ && !pending_) pending_ = table_; // transaction begins with a working copy
        for (const auto& r : rows()) {
            if (r.id == row.id) throw SQLException("duplicate primary key " + std::to_string(row.id));
        }
        rows().push_back(row);
    }
    void commit() {
        if (pending_) table_ = *pending_;
        pending_.reset();
    }
    void rollback() { pending_.reset(); }

private:
    std::vector<Row> table_;                // committed rows
    std::optional<std::vector<Row>> pending_; // working copy of an open transaction
    bool autoCommit_ = true, closed_ = false;
};

class PreparedStatement {
public:
    PreparedStatement(Connection& conn, std::string sql) : conn_(conn), sql_(std::move(sql)) {}
    void setInt(int index, int value) { params_[index] = std::to_string(value); } // 1-based
    void setString(int index, const std::string& value) { params_[index] = value; }

    int executeUpdate() { // understands only the INSERT used below
        conn_.write({std::stoi(params_[1]), params_[2], std::stoi(params_[3])});
        return 1;
    }
    ResultSet executeQuery() { // understands only the SELECT used below
        std::vector<Row> result;
        for (const auto& r : conn_.rows()) if (r.age >= std::stoi(params_[1])) result.push_back(r);
        return ResultSet(result);
    }

private:
    Connection& conn_;
    std::string sql_;
    std::map<int, std::string> params_;
};

Connection getConnection(const std::string& url) { // DriverManager.getConnection
    if (url.rfind("jdbc:mem:", 0) != 0) throw SQLException("No suitable driver found for " + url);
    return Connection();
}

const std::string INSERT = "INSERT INTO students (id, name, age) VALUES (?, ?, ?)";
const std::string QUERY = "SELECT id, name, age FROM students WHERE age >= ?";

void insert(PreparedStatement& ps, int id, const std::string& name, int age) {
    ps.setInt(1, id); // parameter indices start at 1
    ps.setString(2, name);
    ps.setInt(3, age);
    ps.executeUpdate();
}

int main() {
    std::cout << std::boolalpha;
    Connection conn = getConnection("jdbc:mem:school");
    std::cout << "connected to jdbc:mem:school, autoCommit = " << conn.getAutoCommit() << "\n";
    conn.setAutoCommit(false); // group the next statements into one transaction
    PreparedStatement ps(conn, INSERT);
    insert(ps, 1, "Ana", 20);
    insert(ps, 2, "Luis", 22);
    insert(ps, 3, "Marta", 25);
    conn.commit();
    std::cout << "tx 1: inserted Ana, Luis, Marta -> commit\n";

    try {
        insert(ps, 4, "Diego", 23);
        insert(ps, 2, "Luisa", 30); // duplicate primary key
        conn.commit();
    } catch (const SQLException& e) {
        conn.rollback(); // undo everything since the last commit, Diego included
        std::cout << "tx 2: SQLException: " << e.what() << " -> rollback\n";
    }

    PreparedStatement query(conn, QUERY);
    query.setInt(1, 21);
    std::cout << QUERY << "  [1] = 21\n";
    ResultSet rs = query.executeQuery();
    while (rs.next()) { // the cursor starts before the first row
        std::cout << "  " << rs.getInt("id") << " " << rs.getString("name") << " " << rs.getInt("age") << "\n";
    }
    conn.close(); // Java's try-with-resources would do this automatically
    std::cout << "closed by try-with-resources: " << conn.isClosed() << "\n";
}

