from dataclasses import dataclass

# No JDBC here: a tiny in-memory stand-in whose classes and method names mirror java.sql


class SQLException(Exception):
    pass


@dataclass
class Row:
    id: int
    name: str
    age: int


class ResultSet:
    def __init__(self, rows):
        self.rows, self.cursor = rows, -1  # the cursor starts before the first row

    def next(self):
        self.cursor += 1
        return self.cursor < len(self.rows)

    def getInt(self, column):
        return getattr(self.rows[self.cursor], column)

    def getString(self, column):
        return getattr(self.rows[self.cursor], column)


class Connection:
    def __init__(self):
        self.table, self.pending = [], None  # committed rows / working copy of an open transaction
        self.auto_commit, self.closed = True, False

    def getAutoCommit(self):
        return self.auto_commit

    def setAutoCommit(self, on):
        self.auto_commit = on

    def isClosed(self):
        return self.closed

    def prepareStatement(self, sql):
        return PreparedStatement(self, sql)

    def rows(self):
        return self.pending if self.pending is not None else self.table

    def write(self, row):
        if not self.auto_commit and self.pending is None:
            self.pending = list(self.table)  # transaction begins
        if any(r.id == row.id for r in self.rows()):
            raise SQLException(f"duplicate primary key {row.id}")
        self.rows().append(row)

    def commit(self):
        if self.pending is not None:
            self.table = self.pending
        self.pending = None

    def rollback(self):
        self.pending = None

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.closed = True


class PreparedStatement:
    def __init__(self, conn, sql):
        self.conn, self.sql, self.params = conn, sql, {}

    def setInt(self, index, value):  # 1-based, like JDBC
