    setString = setInt

    def executeUpdate(self):  # understands only the INSERT below
        self.conn.write(Row(self.params[1], self.params[2], self.params[3]))
        return 1

    def executeQuery(self):  # understands only the SELECT below
        return ResultSet([r for r in self.conn.rows() if r.age >= self.params[1]])


