// No JDBC here: a tiny in-memory stand-in whose classes and method names mirror java.sql
class SQLException extends Error {}

class ResultSet {
  constructor(rows) {
    this.rows = rows;
    this.cursor = -1; // the cursor starts before the first row
  }
  next() { return ++this.cursor < this.rows.length; }
  getInt(column) { return this.rows[this.cursor][column]; }
  getString(column) { return this.rows[this.cursor][column]; }
}

class Connection {
  constructor() {
    this.table = []; // committed rows
    this.pending = null; // working copy of an open transaction
    this.autoCommit = true;
    this.closed = false;
  }
  getAutoCommit() { return this.autoCommit; }
  setAutoCommit(on) { this.autoCommit = on; }
  isClosed() { return this.closed; }
  close() { this.closed = true; }
  prepareStatement(sql) { return new PreparedStatement(this, sql); }
  rows() { return this.pending ?? this.table; }

  write(row) {
    if (!this.autoCommit && this.pending === null) this.pending = [...this.table]; // transaction begins
    if (this.rows().some((r) => r.id === row.id)) throw new SQLException(`duplicate primary key ${row.id}`);
    this.rows().push(row);
  }
  commit() {
    if (this.pending !== null) this.table = this.pending;
    this.pending = null;
  }
  rollback() { this.pending = null; }
}

class PreparedStatement {
  constructor(conn, sql) {
    this.conn = conn;
    this.sql = sql;
    this.params = {};
  }
  setInt(index, value) { this.params[index] = value; } // 1-based, like JDBC
  setString(index, value) { this.params[index] = value; }
  executeUpdate() { // understands only the INSERT below
    this.conn.write({ id: this.params[1], name: this.params[2], age: this.params[3] });
    return 1;
  }
  executeQuery() { // understands only the SELECT below
    return new ResultSet(this.conn.rows().filter((r) => r.age >= this.params[1]));
  }
}

