import java.util.ArrayList;
import java.util.List;

public class DriverRegistryDemo {
    static class SQLException extends Exception {
        SQLException(String message) { super(message); }
    }

    record Connection(String driver, String database) {}

    // Mirrors java.sql.Driver: each vendor ships one implementation
    interface Driver {
        boolean acceptsURL(String url);
        Connection connect(String url);
    }

    record PrefixDriver(String name, String prefix) implements Driver {
        public boolean acceptsURL(String url) { return url.startsWith(prefix); }
        public Connection connect(String url) { return new Connection(name, url.substring(prefix.length())); }
    }

    static class DriverManager {
        private static final List<Driver> drivers = new ArrayList<>();

        // Real drivers are registered automatically via ServiceLoader (META-INF/services/java.sql.Driver)
        static void registerDriver(Driver driver) { drivers.add(driver); }

        static Connection getConnection(String url) throws SQLException {
            for (Driver driver : drivers) {
                if (driver.acceptsURL(url)) return driver.connect(url); // first driver that accepts wins
            }
            throw new SQLException("No suitable driver found for " + url);
        }
    }

    public static void main(String[] args) {
        DriverManager.registerDriver(new PrefixDriver("MemDriver", "jdbc:mem:"));
        DriverManager.registerDriver(new PrefixDriver("CsvDriver", "jdbc:csv:"));
        System.out.println("registered drivers: MemDriver, CsvDriver");

        String[] urls = {"jdbc:mem:school", "jdbc:csv:/data/grades", "jdbc:mysql://localhost:3306/school"};
        for (String url : urls) {
            String[] parts = url.split(":", 3); // jdbc : subprotocol : subname
            System.out.println(url + " -> subprotocol '" + parts[1] + "', subname '" + parts[2] + "'");
            try {
                Connection conn = DriverManager.getConnection(url); // real: getConnection(url, user, password)
                System.out.println("  accepted by " + conn.driver() + ", database '" + conn.database() + "'");
            } catch (SQLException e) {
                System.out.println("  SQLException: " + e.getMessage());
            }
        }
    }
}

