#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

struct SQLException : std::runtime_error {
    using std::runtime_error::runtime_error;
};

struct Connection {
    std::string driver;
    std::string database;
};

// Mirrors java.sql.Driver: each vendor ships one implementation
struct PrefixDriver {
    std::string name;
    std::string prefix;
    bool acceptsURL(const std::string& url) const { return url.rfind(prefix, 0) == 0; }
    Connection connect(const std::string& url) const { return {name, url.substr(prefix.size())}; }
};

class DriverManager {
public:
    // Real Java drivers are registered automatically via ServiceLoader (META-INF/services/java.sql.Driver)
    static void registerDriver(const PrefixDriver& driver) { drivers().push_back(driver); }

    static Connection getConnection(const std::string& url) {
        for (const auto& driver : drivers()) {
            if (driver.acceptsURL(url)) return driver.connect(url); // first driver that accepts wins
        }
        throw SQLException("No suitable driver found for " + url);
    }

private:
    static std::vector<PrefixDriver>& drivers() {
        static std::vector<PrefixDriver> registry;
        return registry;
    }
};

int main() {
    DriverManager::registerDriver({"MemDriver", "jdbc:mem:"});
    DriverManager::registerDriver({"CsvDriver", "jdbc:csv:"});
    std::cout << "registered drivers: MemDriver, CsvDriver\n";

    for (std::string url : {"jdbc:mem:school", "jdbc:csv:/data/grades", "jdbc:mysql://localhost:3306/school"}) {
        std::size_t first = url.find(':'), second = url.find(':', first + 1); // jdbc : subprotocol : subname
        std::cout << url << " -> subprotocol '" << url.substr(first + 1, second - first - 1)
                  << "', subname '" << url.substr(second + 1) << "'\n";
        try {
            Connection conn = DriverManager::getConnection(url);
            std::cout << "  accepted by " << conn.driver << ", database '" << conn.database << "'\n";
        } catch (const SQLException& e) {
            std::cout << "  SQLException: " << e.what() << "\n";
        }
    }
}

