// Mirrors java.sql.Driver: each vendor ships one implementation
class PrefixDriver {
  constructor(name, prefix) {
    this.name = name;
    this.prefix = prefix;
  }
  acceptsURL(url) { return url.startsWith(this.prefix); }
  connect(url) { return { driver: this.name, database: url.slice(this.prefix.length) }; }
}

const DriverManager = {
