import java.util.Map;
import java.util.TreeMap;

public class ConnectionTransactionDemo {
    public static void main(String[] args) {
        Connection kept;
        // Real: try (Connection conn = DriverManager.getConnection(url, user, password))
        try (Connection conn = new Connection(Map.of("A", 100, "B", 50))) {
            kept = conn;
            System.out.println("open: autoCommit = " + conn.getAutoCommit() + ", isClosed = " + conn.isClosed());
            Statement st = conn.createStatement();
            st.executeUpdate("UPDATE accounts SET balance = balance + 10 WHERE id = 'A'");
            System.out.println("auto-commit deposit of 10 into A -> committed " + conn.snapshot());

            conn.setAutoCommit(false);
            st.executeUpdate("UPDATE accounts SET balance = balance - 30 WHERE id = 'A'");
            st.executeUpdate("UPDATE accounts SET balance = balance + 30 WHERE id = 'B'");
            System.out.println("tx 1: moved 30 A->B, not committed yet -> committed " + conn.snapshot());
            conn.commit();
            System.out.println("tx 1: commit() -> committed " + conn.snapshot());

            try {
                st.executeUpdate("UPDATE accounts SET balance = balance + 500 WHERE id = 'B'");
                st.executeUpdate("UPDATE accounts SET balance = balance - 500 WHERE id = 'A'");
                conn.commit();
            } catch (SQLException e) {
                System.out.println("tx 2: credit B 500 ok, debit A 500 -> SQLException: " + e.getMessage());
