// Stand-in for java.sql.Connection over one in-memory table: accounts(id, balance CHECK (balance >= 0))
class Connection {
public:
    explicit Connection(std::map<std::string, int> initial) : committed_(std::move(initial)) {}
    ~Connection() { close(); } // RAII plays the role of try-with-resources

    bool getAutoCommit() const { return autoCommit_; }
    void setAutoCommit(bool on) { autoCommit_ = on; }
    bool isClosed() const { return closed_; }
    std::string snapshot() const { return "A=" + std::to_string(committed_.at("A")) + " B=" + std::to_string(committed_.at("B")); }

    // Statement.executeUpdate for one shape: UPDATE accounts SET balance = balance <+|-> <n> WHERE id = '<id>'
    int executeUpdate(const std::string& sql) {
        if (closed_) throw SQLException("Connection is closed");
        std::istringstream in(sql);
        std::vector<std::string> t;
        for (std::string word; in >> word;) t.push_back(word);
        int amount = std::stoi(t[7]);
        apply(t[11].substr(1, t[11].size() - 2), t[6] == "+" ? amount : -amount);
        return 1;
    }
    void createStatement() const {
        if (closed_) throw SQLException("Connection is closed");
    }

    void commit() {
        if (pending_) committed_ = *pending_;
        pending_.reset();
    }
    void rollback() { pending_.reset(); }
    void close() {
        pending_.reset();
        closed_ = true;
    }

private:
    void apply(const std::string& id, int delta) {
        if (!pending_) pending_ = committed_; // first write opens a transaction
        int next = pending_->at(id) + delta;
        if (next < 0) throw SQLException("CHECK constraint failed: balance >= 0");
        (*pending_)[id] = next;
        if (autoCommit_) commit(); // auto-commit: every statement is its own transaction
    }

    std::map<std::string, int> committed_;
    std::optional<std::map<std::string, int>> pending_; // working copy while a transaction is open
    bool autoCommit_ = true, closed_ = false;
};

int main() {
    std::cout << std::boolalpha;
    Connection conn({{"A", 100}, {"B", 50}});
    std::cout << "open: autoCommit = " << conn.getAutoCommit() << ", isClosed = " << conn.isClosed() << "\n";
    conn.executeUpdate("UPDATE accounts SET balance = balance + 10 WHERE id = 'A'");
    std::cout << "auto-commit deposit of 10 into A -> committed " << conn.snapshot() << "\n";

    conn.setAutoCommit(false);
    conn.executeUpdate("UPDATE accounts SET balance = balance - 30 WHERE id = 'A'");
    conn.executeUpdate("UPDATE accounts SET balance = balance + 30 WHERE id = 'B'");
    std::cout << "tx 1: moved 30 A->B, not committed yet -> committed " << conn.snapshot() << "\n";
    conn.commit();
    std::cout << "tx 1: commit() -> committed " << conn.snapshot() << "\n";

    try {
