// Stand-in for java.sql.Statement plus a toy engine for exactly four SQL shapes; values are stored as text
class Statement {
    private List<String> columns = new ArrayList<>();
    private final List<List<String>> table = new ArrayList<>();
    private final List<String> batch = new ArrayList<>();
    private ResultSet lastResult;
    private int lastCount = -1;

    private static String value(String token) { return token.replace("'", ""); }

    private Object run(String sql) {
        String[] t = sql.split(" ");
        String inParens = sql.contains("(") ? sql.substring(sql.indexOf('(') + 1, sql.lastIndexOf(')')) : "";
        switch (t[0]) {
            case "CREATE": columns = List.of(inParens.split(", ")); return 0;
            case "INSERT": {
                List<String> row = new ArrayList<>();
                for (String v : inParens.split(", ")) row.add(value(v));
                table.add(row);
                return 1;
            }
            case "UPDATE": { // UPDATE t SET col = v WHERE col = v
                int set = columns.indexOf(t[3]), where = columns.indexOf(t[7]), count = 0;
                for (List<String> row : table) {
                    if (row.get(where).equals(value(t[9]))) { row.set(set, value(t[5])); count++; }
                }
                return count;
            }
            default: return new ResultSet(table); // SELECT code, credits FROM t (all columns, all rows)
        }
    }

    boolean execute(String sql) {
        Object result = run(sql);
        lastResult = result instanceof ResultSet rs ? rs : null;
        lastCount = result instanceof Integer n ? n : -1;
        return lastResult != null;
    }
    int getUpdateCount() { return lastCount; }
    ResultSet getResultSet() { return lastResult; }
    int executeUpdate(String sql) { return (Integer) run(sql); }
    ResultSet executeQuery(String sql) { return (ResultSet) run(sql); }
    void addBatch(String sql) { batch.add(sql); }
    int[] executeBatch() {
        int[] counts = new int[batch.size()];
        for (int i = 0; i < counts.length; i++) counts[i] = executeUpdate(batch.get(i));
        batch.clear();
        return counts;
    }
}

