struct ResultSet {
    std::vector<Row> rows;
    int cursor = -1; // before the first row
    bool next() { return ++cursor < static_cast<int>(rows.size()); }
    std::string getString(int column) const { return rows[cursor][column - 1]; } // 1-based
};

std::vector<std::string> split(const std::string& s, const std::string& sep) {
    std::vector<std::string> parts;
    std::size_t start = 0, pos;
    while ((pos = s.find(sep, start)) != std::string::npos) {
        parts.push_back(s.substr(start, pos - start));
        start = pos + sep.size();
    }
    parts.push_back(s.substr(start));
    return parts;
}

std::string value(std::string token) {
    token.erase(std::remove(token.begin(), token.end(), '\''), token.end());
    return token;
}

// Stand-in for java.sql.Statement plus a toy engine for exactly four SQL shapes; values are stored as text
class Statement {
public:
    bool execute(const std::string& sql) {
        isQuery_ = sql.rfind("SELECT", 0) == 0;
        if (isQuery_) {
            lastResult_ = executeQuery(sql);
            lastCount_ = -1;
        } else {
            lastCount_ = executeUpdate(sql);
        }
        return isQuery_;
    }
    int getUpdateCount() const { return lastCount_; }
    const ResultSet& getResultSet() const { return lastResult_; }
    ResultSet executeQuery(const std::string&) { return ResultSet{table_}; } // SELECT code, credits: all rows

    int executeUpdate(const std::string& sql) {
        auto t = split(sql, " ");
        std::string inParens;
        if (sql.find('(') != std::string::npos) inParens = sql.substr(sql.find('(') + 1, sql.rfind(')') - sql.find('(') - 1);
        if (t[0] == "CREATE") {
            columns_ = split(inParens, ", ");
            return 0;
        }
        if (t[0] == "INSERT") {
            Row row;
            for (const auto& v : split(inParens, ", ")) row.push_back(value(v));
            table_.push_back(row);
            return 1;
        }
        // UPDATE t SET col = v WHERE col = v
        auto index = [&](const std::string& c) { return std::find(columns_.begin(), columns_.end(), c) - columns_.begin(); };
        auto set = index(t[3]), where = index(t[7]);
        int count = 0;
        for (auto& row : table_) {
            if (row[where] == value(t[9])) {
                row[set] = value(t[5]);
                ++count;
            }
        }
        return count;
    }

    void addBatch(const std::string& sql) { batch_.push_back(sql); }
    std::vector<int> executeBatch() {
        std::vector<int> counts;
        for (const auto& sql : batch_) counts.push_back(executeUpdate(sql));
        batch_.clear();
        return counts;
    }

private:
    std::vector<std::string> columns_;
    std::vector<Row> table_;
    std::vector<std::string> batch_;
    ResultSet lastResult_;
    int lastCount_ = -1;
    bool isQuery_ = false;
};

