      const where = this.columns.indexOf(t[7]);
      const matches = this.table.filter((row) => row[where] === value(t[9]));
      matches.forEach((row) => { row[set] = value(t[5]); });
      return matches.length;
    }
    return new ResultSet(this.table); // SELECT code, credits FROM t: all columns, all rows
  }

  execute(sql) {
    const result = this.run(sql);
    const isQuery = result instanceof ResultSet;
    this.lastResult = isQuery ? result : null;
    this.lastCount = isQuery ? -1 : result;
    return isQuery;
  }
  getUpdateCount() { return this.lastCount; }
  getResultSet() { return this.lastResult; }
  executeUpdate(sql) { return this.run(sql); }
  executeQuery(sql) { return this.run(sql); }
  addBatch(sql) { this.batch.push(sql); }
  executeBatch() {
    const counts = this.batch.map((sql) => this.executeUpdate(sql));
    this.batch = [];
    return counts;
  }
}

