import java.util.ArrayList;
import java.util.List;

public class ResultSetCursorDemo {
    record Student(int id, String name, Double gpa) {} // Double, not double, so it can hold null

    // Map the current row; wasNull() must be called right after the getter it refers to
    static Student toStudent(ResultSet rs) throws SQLException {
        double raw = rs.getDouble("gpa");
        Double gpa = rs.wasNull() ? null : raw; // ask now: the next getter resets wasNull()
        return new Student(rs.getInt("id"), rs.getString(2), gpa);
    }

    static String gpaText(Double gpa) { return gpa == null ? "null" : String.format("%.2f", gpa); }

    public static void main(String[] args) throws SQLException {
        // Real: ResultSet rs = stmt.executeQuery("SELECT id, name, gpa FROM students ORDER BY id");
        ResultSet rs = new ResultSet(new Object[][]{{1, "Ana", 3.8}, {2, "Luis", null}, {3, "Marta", 3.25}});
        try {
            rs.getString(1);
        } catch (SQLException e) {
            System.out.println("getString(1) before next() -> SQLException: " + e.getMessage());
        }

        List<Student> students = new ArrayList<>();
        int row = 0;
        while (rs.next()) {
            row++;
            double gpa = rs.getDouble("gpa");
            boolean wasNull = rs.wasNull();
            System.out.printf("row %d: id=%d name=%s gpa=%.2f (wasNull=%b)%n", row, rs.getInt("id"), rs.getString(2), gpa, wasNull);
            students.add(toStudent(rs));
