// Stand-in for java.sql.ResultSet over rows with columns (id INT, name VARCHAR, gpa DOUBLE NULL)
class ResultSet {
    private static final List<String> LABELS = List.of("id", "name", "gpa");
    private final Object[][] rows;
    private int cursor = -1; // before the first row
    private boolean lastWasNull;

    ResultSet(Object[][] rows) { this.rows = rows; }

    boolean next() { return ++cursor < rows.length; }

    private Object read(int column) throws SQLException { // column is 1-based
        if (cursor < 0) throw new SQLException("Before start of result set");
        if (cursor >= rows.length) throw new SQLException("After end of result set");
        Object value = rows[cursor][column - 1];
        lastWasNull = value == null;
        return value;
    }

    int getInt(String label) throws SQLException { Object v = read(LABELS.indexOf(label) + 1); return v == null ? 0 : (Integer) v; }
    String getString(int column) throws SQLException { return (String) read(column); }
    double getDouble(String label) throws SQLException { Object v = read(LABELS.indexOf(label) + 1); return v == null ? 0.0 : (Double) v; }
    boolean wasNull() { return lastWasNull; }
}

