#include <cstdio>
#include <iostream>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

struct SQLException : std::runtime_error {
    using std::runtime_error::runtime_error;
};

struct DbRow {
    int id;
    std::string name;
    std::optional<double> gpa; // nullable column
};

// Stand-in for java.sql.ResultSet over rows with columns (id INT, name VARCHAR, gpa DOUBLE NULL)
class ResultSet {
public:
    explicit ResultSet(std::vector<DbRow> rows) : rows_(std::move(rows)) {}
    bool next() { return ++cursor_ < static_cast<int>(rows_.size()); }

    int getInt(const std::string&) { lastWasNull_ = false; return current().id; }  // only "id" is an INT column
    std::string getString(int column) { // 1-based; column 2 is name
        lastWasNull_ = false;
        return column == 2 ? current().name : std::to_string(current().id);
    }
    double getDouble(const std::string&) { // only "gpa" is a DOUBLE column
        const auto& gpa = current().gpa;
        lastWasNull_ = !gpa.has_value();
        return gpa.value_or(0.0); // SQL NULL comes back as 0.0
    }
    bool wasNull() const { return lastWasNull_; }

private:
    const DbRow& current() const {
        if (cursor_ < 0) throw SQLException("Before start of result set");
        if (cursor_ >= static_cast<int>(rows_.size())) throw SQLException("After end of result set");
        return rows_[cursor_];
    }
    std::vector<DbRow> rows_;
    int cursor_ = -1; // before the first row
    bool lastWasNull_ = false;
};

struct Student {
    int id;
    std::string name;
    std::optional<double> gpa;
};

// Map the current row; wasNull() must be called right after the getter it refers to
Student toStudent(ResultSet& rs) {
    double gpa = rs.getDouble("gpa");
    std::optional<double> value = rs.wasNull() ? std::nullopt : std::optional<double>(gpa); // ask now: the next getter resets wasNull()
    return {rs.getInt("id"), rs.getString(2), value};
}

int main() {
    ResultSet rs({{1, "Ana", 3.8}, {2, "Luis", std::nullopt}, {3, "Marta", 3.25}});
    try {
        rs.getString(1);
    } catch (const SQLException& e) {
        std::cout << "getString(1) before next() -> SQLException: " << e.what() << "\n";
    }

    std::vector<Student> students;
    int row = 0;
    while (rs.next()) {
        ++row;
        double gpa = rs.getDouble("gpa");
        bool wasNull = rs.wasNull();
        std::printf("row %d: id=%d name=%s gpa=%.2f (wasNull=%s)\n", row, rs.getInt("id"), rs.getString(2).c_str(), gpa, wasNull ? "true" : "false");
        students.push_back(toStudent(rs));
    }
    std::cout << "next() returned false: the cursor is after the last row\n";
    for (const auto& s : students) {
        char gpa[16] = "null";
        if (s.gpa) std::snprintf(gpa, sizeof gpa, "%.2f", *s.gpa);
        std::cout << "mapped: Student(" << s.id << ", " << s.name << ", " << gpa << ")\n";
    }
}

