class ResultSet:
    """Stand-in for java.sql.ResultSet over rows with columns (id INT, name VARCHAR, gpa DOUBLE NULL)."""
    LABELS = ["id", "name", "gpa"]

    def __init__(self, rows):
        self.rows, self.cursor, self.last_was_null = rows, -1, False  # cursor starts before the first row

    def next(self):
        self.cursor += 1
        return self.cursor < len(self.rows)

    def _read(self, column):  # column is 1-based
        if self.cursor < 0:
            raise SQLException("Before start of result set")
        if self.cursor >= len(self.rows):
            raise SQLException("After end of result set")
        value = self.rows[self.cursor][column - 1]
        self.last_was_null = value is None
        return value

    def getInt(self, label):
        value = self._read(self.LABELS.index(label) + 1)
        return 0 if value is None else value

    def getString(self, column):
        return self._read(column)

    def getDouble(self, label):
        value = self._read(self.LABELS.index(label) + 1)
        return 0.0 if value is None else value  # SQL NULL comes back as 0.0

    def wasNull(self):
        return self.last_was_null


