import java.util.ArrayList;
import java.util.List;

public class SqlInjectionDemo {
    static class SQLException extends Exception {
        SQLException(String message) { super(message); }
    }

    record User(String name, String role) {
        String get(String column) { return column.equals("name") ? name : role; }
        public String toString() { return name + "/" + role; }
    }

    static final List<User> USERS = List.of(new User("alice", "admin"), new User("bob", "user"));

    // Toy engine for "SELECT name, role FROM users WHERE a = b [OR c = d ...]": it parses whatever text it gets
    static List<User> runSql(String sql) {
        List<User> result = new ArrayList<>();
        String[] clauses = sql.substring(sql.indexOf(" WHERE ") + 7).split(" OR ");
        for (User u : USERS) {
            for (String clause : clauses) {
                String[] sides = clause.split("=", 2);
                if (operand(sides[0].trim(), u).equals(operand(sides[1].trim(), u))) { result.add(u); break; }
            }
        }
        return result;
    }

    static String operand(String token, User u) { // 'text' is a literal, anything else a column
        return token.startsWith("'") ? token.substring(1, token.length() - 1) : u.get(token);
    }

    // DON'T: user input becomes part of the SQL text
    static String byConcatenation(String input) {
        return "SELECT name, role FROM users WHERE name = '" + input + "'";
    }

    // Stand-in for java.sql.PreparedStatement: the SQL shape is fixed; parameters are only data
    static class PreparedStatement {
        private final String column;
        private final String[] params = new String[2];

        PreparedStatement(String sql) { column = sql.substring(sql.indexOf(" WHERE ") + 7, sql.indexOf(" = ?")); }

        void setString(int index, String value) throws SQLException {
            if (index < 1 || index > 1) throw new SQLException("parameter index " + index + " is out of range 1..1");
            params[index] = value;
        }

        List<User> executeQuery() {
            List<User> result = new ArrayList<>();
            for (User u : USERS) if (u.get(column).equals(params[1])) result.add(u); // plain value comparison
            return result;
        }
    }

    public static void main(String[] args) {
        // Real: PreparedStatement ps = conn.prepareStatement("SELECT name, role FROM users WHERE name = ?");
        PreparedStatement ps = new PreparedStatement("SELECT name, role FROM users WHERE name = ?");
        for (String input : new String[]{"bob", "' OR '1'='1"}) {
            System.out.println("input: " + input);
            String sql = byConcatenation(input);
            System.out.println("  concatenated SQL: " + sql);
            System.out.println("  concatenated -> " + runSql(sql));
            try {
                ps.setString(1, input);
            } catch (SQLException e) {
                throw new IllegalStateException(e);
            }
            System.out.println("  prepared     -> " + ps.executeQuery());
        }
        try {
            ps.setString(0, "bob");
        } catch (SQLException e) {
            System.out.println("setString(0, ...) -> SQLException: " + e.getMessage());
        }
    }
}

