struct SQLException : std::runtime_error {
    using std::runtime_error::runtime_error;
};

struct User {
    std::string name, role;
    std::string get(const std::string& column) const { return column == "name" ? name : role; }
};

const std::vector<User> USERS = {{"alice", "admin"}, {"bob", "user"}};

std::string trim(const std::string& s) {
    auto b = s.find_first_not_of(' '), e = s.find_last_not_of(' ');
    return b == std::string::npos ? "" : s.substr(b, e - b + 1);
}

std::string operand(const std::string& token, const User& u) { // 'text' is a literal, anything else a column
    return token[0] == '\'' ? token.substr(1, token.size() - 2) : u.get(token);
}

// Toy engine for "SELECT name, role FROM users WHERE a = b [OR c = d ...]": it parses whatever text it gets
std::vector<User> runSql(const std::string& sql) {
    std::string where = sql.substr(sql.find(" WHERE ") + 7);
    std::vector<std::string> clauses;
    for (std::size_t start = 0, pos;; start = pos + 4) {
        pos = where.find(" OR ", start);
        clauses.push_back(where.substr(start, pos == std::string::npos ? std::string::npos : pos - start));
        if (pos == std::string::npos) break;
    }
    std::vector<User> result;
    for (const auto& u : USERS) {
        for (const auto& clause : clauses) {
            auto eq = clause.find('=');
            if (operand(trim(clause.substr(0, eq)), u) == operand(trim(clause.substr(eq + 1)), u)) {
                result.push_back(u);
                break;
            }
        }
    }
    return result;
}

// DON'T: user input becomes part of the SQL text
std::string byConcatenation(const std::string& input) {
    return "SELECT name, role FROM users WHERE name = '" + input + "'";
}

// Stand-in for java.sql.PreparedStatement: the SQL shape is fixed; parameters are only data
class PreparedStatement {
public:
    explicit PreparedStatement(const std::string& sql) {
        auto start = sql.find(" WHERE ") + 7;
        column_ = sql.substr(start, sql.find(" = ?") - start);
    }
    void setString(int index, const std::string& value) {
        if (index < 1 || index > 1) throw SQLException("parameter index " + std::to_string(index) + " is out of range 1..1");
        params_[index] = value;
    }
    std::vector<User> executeQuery() const {
        std::vector<User> result;
        for (const auto& u : USERS) if (u.get(column_) == params_.at(1)) result.push_back(u); // plain value comparison
        return result;
    }

private:
    std::string column_;
    std::map<int, std::string> params_;
};

std::string show(const std::vector<User>& users) {
    std::string out = "[";
    for (std::size_t i = 0; i < users.size(); ++i) out += (i ? ", " : "") + users[i].name + "/" + users[i].role;
    return out + "]";
}

