        std::string sql = byConcatenation(input);
        std::cout << "  concatenated SQL: " << sql << "\n";
        std::cout << "  concatenated -> " << show(runSql(sql)) << "\n";
        ps.setString(1, input);
        std::cout << "  prepared     -> " << show(ps.executeQuery()) << "\n";
    }
    try {
        ps.setString(0, "bob");
    } catch (const SQLException& e) {
        std::cout << "setString(0, ...) -> SQLException: " << e.what() << "\n";
    }
}

