class Solution {
    static String insertSql(String table, List<String> columns) {
        String names = String.join(", ", columns);
        // one "?" per column; the values are bound later with setString, setInt, ...
        String marks = String.join(", ", Collections.nCopies(columns.size(), "?"));
        return "INSERT INTO " + table + " (" + names + ") VALUES (" + marks + ")";
    }
}

