import java.util.*;

class Solution {
    static Map<String, Integer> totalsByCustomer(List<Map<String, Object>> rows) {
        Map<String, Integer> totals = new TreeMap<>();
        for (Map<String, Object> row : rows) {
            // like rs.getString("customer") and rs.getInt("amount")
            String customer = (String) row.get("customer");
            int amount = (Integer) row.get("amount");
            totals.merge(customer, amount, Integer::sum);
        }
        return totals;
    }
}

